import { ElementType, ComponentPropsWithoutRef, ComponentPropsWithRef } from 'react';

type PrimitiveProps<TElement extends ElementType = "div"> = Omit<ComponentPropsWithoutRef<TElement>, "asChild"> & {
    asChild?: boolean;
};
type PrimitiveRef<TElement extends ElementType> = ComponentPropsWithRef<TElement>["ref"];

export type { PrimitiveProps as P, PrimitiveRef as a };
